package com.example

import com.example.ExamQuestionHelper.QSpec

internal object BuddhismG11LiveExamDisciplesBank {
  private const val T = "බුද්ධ චරිතය හා ශ්‍රාවක චරිත"

  private fun q(
    stem: String,
    c: String,
    d1: String,
    d2: String,
    d3: String,
    exp: String
  ) = QSpec(T, stem, c, listOf(d1, d2, d3), exp)

  fun questions(): List<QSpec> = listOf(
    q("මුගලන් මහරහතන් වහන්සේ විසින් ඍද්ධි බලයෙන් දමනය කරන ලද බලවත් නාග රාජයා කවුද?", "නන්දෝපනන්ද නා රජු", "මුචලින්ද නා රජු", "කාල නා රජු", "ඒරාපථ නා රජු", "සුමන සාමණේරයන් පැරදවීමට තැත් කළ නන්දෝපනන්ද දමනය කළහ."),
    q("ප්‍රථම සංගායනාවට ආසන්නතම හේතුව වූ අකැප ප්‍රකාශය කළ මහලු භික්ෂුව කවුද?", "සුභද්‍ර නම් මහලු භික්ෂුව", "ඡන්න භික්ෂුව", "උපනන්ද භික්ෂුව", "අස්සජී පුනබ්බසුක", "බුදු පිරිනිවනින් පසු විනය ශික්ෂා ගැන අකැප වදන් කී සුභද්‍ර නිසා සංගායනාව ඇරඹිණි."),
    q("පසේනදී කොසොල් රජු මල්ලිකා දේවියගේ උපදෙසින් පැවැත්වූ ශ්‍රේෂ්ඨ දානය කුමක්ද?", "අසදෘශ මහා දානය", "වෙළඳ දානය", "කඨින දානය", "පිණ්ඩපාත දානය", "විශේෂ පූජාවන්ගෙන් යුතුව පැවැත්වූ අසදෘශ දානය කීර්තිමත් විය."),
    q("පටාචාරා තෙරණියගෙන් ධර්මය අසා පැවිදිව රහත් වූ කුල කාන්තාවන් ගණන කීයද?", "පන්සියයක් කාන්තාවෝ", "සියයක් කාන්තාවෝ", "දහසක් කාන්තාවෝ", "විසිපස්දෙනෙක්", "ශෝකයට පත් පන්සියයක් කතුන්ට පටාචාරා තෙරණිය නිවන් මඟ පෙන්වූවාය."),
    q("බුදුරදුන්ගේ දකුණු පාදයේ ගල් පතුරක් වැදී තුවාල වූයේ කුමන සිදුවීමකදීද?", "දේවදත්ත හිමි ගල් පෙරළීමේදී", "මාර පරාජයේදී", "නාලාගිරි ඇතු පැමිණි විට", "විශාලා නුවර වසංගතයේදී", "ගිජ්ඣකූට පර්වතය මතින් දේවදත්ත ගලක් පෙරළූ අවස්ථාවේ ගල් පතුරක් වැදුණි."),
    q("ආනන්ද හිමියන් බුදුරදුන්ගේ ස්ථිර උපස්ථායක තනතුර භාර ගැනීමට පෙර ඉල්ලූ වර ගණන කීයද?", "වර අටකි", "වර හතරකි", "වර පහකි", "වර දොළහකි", "ප්‍රතික්ෂේප කළ වර 4ක් හා ඉල්ලූ වර 4ක් ලෙස වර 8ක් ඉල්ලා සිටියහ."),
    q("ධම්මික උපාසක තුමා මරණාසන්න මොහොතේදී ශ්‍රවණය කළ සූත්‍රය කුමක්ද?", "සතිපට්ඨාන සූත්‍රය", "රතන සූත්‍රය", "ආටානාටිය සූත්‍රය", "මංගල සූත්‍රය", "භික්ෂූන් ලවා සතිපට්ඨාන සූත්‍රය අසා තුසිත දෙව්ලොව උපන්නේය."),
    q("බුද්ධ ශාසනයේ රළු සිවුරු දැරීමෙන් අග්‍රස්ථානය ලැබූ භික්ෂුව කවුද?", "මෝඝරාජ හිමි", "මහා කාශ්‍යප හිමි", "රේවත හිමි", "කංඛාරේවත හිමි", "මෝඝරාජ හිමියන් රළු සිවුරු දැරීමෙහි අග්‍රස්ථානය ලැබූහ."),
    q("ආරණ්‍යවාසී භික්ෂූන් අතර අග්‍රස්ථානය ලැබූ සැරියුත් හිමියන්ගේ බාල සොහොයුරා කවුද?", "ඛදිරවනිය රේවත හිමි", "චුන්ද හිමි", "උපසේන හිමි", "නන්ද හිමි", "කිහිරි වනයේ විසූ ඛදිරවනිය රේවත හිමි ආරණ්‍යවාසීන් අතර අග්‍ර විය."),
    q("ශ්‍රද්ධාවෙන් මුක්ත වූ (සද්ධාධිමුත්ත) භික්ෂූන් අතර අග්‍රස්ථානය ලැබූ හිමියන් කවුද?", "වක්කලී හිමි", "සෝභිත හිමි", "කාලුදායි හිමි", "රාධ හිමි", "බලවත් ශ්‍රද්ධාව නිසා වක්කලී හිමි සද්ධාධිමුත්තයන් අතර අග්‍ර විය."),
    q("කෙටි අවවාදයකින් සිත දමනය කර ක්ෂණිකව රහත් වූ භික්ෂුව කවුද?", "බාහිය දාරුචීරිය හිමි", "පිංගිය හිමි", "මේඝිය හිමි", "සංගාරව හිමි", "'දිට්ඨේ දිට්ඨමත්තං භවිස්සති' යන අවවාදයෙන් බාහිය දාරුචීරිය රහත් විය."),
    q("බුදුරදුන් සමඟ උපන් 'සහජාත වස්තු හත' අතරට අයත් නොවන්නේ කවුද?", "සැරියුත් හිමි", "යසෝධරා දේවිය", "ආනන්ද හිමි", "කාලුදායි ඇමති", "යසෝධරා, ආනන්ද, චන්න, කාලුදායි, කන්ථක අසු, මහා බෝධිය, සතර නිධානය සහජාතයන්ය."),
    q("බුදුරදුන් සමඟ වාදයට පැමිණ පංචස්කන්ධයේ අනාත්ම බව ඉදිරියේ පරාජය වූ වාදකයා කවුද?", "සච්චක පරිබ්‍රාජක", "දීඝනඛ පරිබ්‍රාජක", "මගන්දිය බමුණා", "වච්ඡගොත්ත පරිබ්‍රාජක", "චූලසච්චක සූත්‍රයේදී සච්චක තම මතය අත්හැරියේය."),
    q("බුදුරදුන් තෙවන වස් කාලය ගත කරන ලද්දේ කුමන නගරයේදීද?", "රජගහ නුවර", "සැවැත් නුවර", "විශාලා නුවර", "කොසඹෑ නුවර", "දෙවන, තෙවන හා සිව්වන වස් කාලයන් රජගහ නුවර වේළුවනාරාමයේ ගත කළහ."),
    q("බුදුරදුන් දහවන වස් කාලය හුදෙකලාව පාරිලෙය්‍ය වනයේ ගත කිරීමට හේතුව කුමක්ද?", "කොසඹෑ නුවර භික්ෂූන්ගේ අසමගිය", "රජුගේ ආරාධනාව", "දුර්භික්ෂයක් ඇතිවීම", "ධර්ම සංගායනාවක් පැවැත්වීම", "විනයධර හා ධර්මධර භික්ෂූන්ගේ විවාදය නිසා පාරිලෙය්‍ය වනයට වැඩම කළහ."),
    q("පාරිලෙය්‍ය වනයේදී බුදුරදුන්ට පැන් හා පලතුරු පිළිගන්වා උපස්ථාන කළේ කවුද?", "පාරිලෙය්‍ය ඇතු හා වඳුරා", "නාලාගිරි ඇතු", "චණ්ඩාල පිරිසක්", "වන දේවතාවියක්", "පාරිලෙය්‍ය හස්තියා සෙනෙහසින් බුදුරදුන්ට උවටැන් කළේය."),
    q("බුදුරජාණන් වහන්සේ වැඩිම වස් කාල ගණනක් (වස් 19ක්) වැඩ සිටියේ කුමන විහාරයේද?", "සැවැත් නුවර ජේතවනාරාමයේ", "සැවැත් නුවර පූර්වාරාමයේ", "රජගහ නුවර වේළුවනාරාමයේ", "විශාලා නුවර කූටාගාර ශාලාවේ", "ජේතවනාරාමයේ වස් 19ක් හා පූර්වාරාමයේ වස් 6ක් වැඩ සිටියහ."),
    q("අනේපිඬු සිටුතුමාගේ දියණියක වී උග්ග නගරයේ පිරිස බුදුදහමට යොමු කළේ කවුද?", "චූලසුභද්‍රාව", "සුජාතාව", "විශාඛාව", "ධම්මදින්නාව", "චූලසුභද්‍රාව තෙරුවන් ගුණ පැහැදිලි කර සිටු පවුල පැහැදවූවාය."),
    q("මනාපදායී උපාසකයන් අතර අග්‍රස්ථානය ලැබූ විශාලා නුවර සිටුතුමා කවුද?", "උග්ග ගෘහපති", "චිත්ත ගෘහපති", "සීහ සේනාපති", "භල්ලුක සිටු", "තමන් කැමතිම ආහාරපාන සංඝයාට පිදූ උග්ග ගෘහපතිතුමා අග්‍ර විය."),
    q("සැරියුත් හිමියන්ගේ ගිහි නාමය කුමක් වීද?", "උපතිස්ස", "කෝලිත", "අසිත", "සුදත්ත", "උපතිස්ස ගමේ සාරී බැමිණියගේ පුත් උපතිස්ස සැරියුත් හිමි නම් විය."),
    q("මුගලන් හිමියන්ගේ ගිහි නාමය කුමක් වීද?", "කෝලිත", "උපතිස්ස", "නන්ද", "භද්දිය", "කෝලිත ගමේ මොග්ගලී බැමිණියගේ පුත් කෝලිත මුගලන් හිමි නම් විය."),
    q("උපතිස්ස හා කෝලිත මිතුරන් දෙදෙනා ගිහිගෙය කලකිරුණේ කුමන උත්සවය නැරඹීමෙන්ද?", "ගිරග්ග සමජ්ජ උත්සවය", "වසන්ත උත්සවය", "නැකැත් උත්සවය", "කාර්තික උත්සවය", "ප්‍රේක්ෂකයන්ගේ හා නළුවන්ගේ අනිත්‍ය ස්වභාවය දැක ඔවුහු කලකිරුණහ."),
    q("කිඹුල්වත්පුර රෝහිණී නදියේ ජල ගැටුම සමථයකට පත් කිරීමට බුදුරදුන් දෙසූ ජාතකය කුමක්ද?", "ඵන්දන ජාතකය", "වෙස්සන්තර ජාතකය", "කුස ජාතකය", "උම්මග්ග ජාතකය", "ශාක්‍ය හා කෝලිය වංශිකයන්ගේ යුද්ධය නවතා අන්‍යෝන්‍ය සමගිය ඇති කළහ."),
    q("දේවදත්ත හිමි විසින් බුදුරදුන් මැරවීමට යෙදවූ දුනුවායන්ට සිදුවූයේ කුමක්ද?", "ධර්මය අසා සෝවාන් වීම", "ආපසු පලා යාම", "රජු විසින් සිරගත කිරීම", "ගල් ගැසීමට තැත් කිරීම", "බුදුරදුන්ගේ මෛත්‍රිය ඉදිරියේ දුනුවායෝ දහම් අසා ශ්‍රාවකයෝ වූහ."),
    q("බුදුරදුන් විසින් 'බ්‍රහ්මදණ්ඩය' පැනවීමට නියම කළ භික්ෂුව කවුද?", "ඡන්න හිමි", "දේවදත්ත හිමි", "උදායි හිමි", "මෙත්තිය හිමි", "මානය දුරු කිරීමට බුදු පිරිනිවනින් පසු ඡන්න හිමිට බ්‍රහ්මදණ්ඩය පනවා පසුව රහත් විය."),
    q("කුරිරු ලෙස ක්‍රියා කළ 'වේරංජා' නුවර වස් කාලයේදී බුදුපාමොක් සඟනට ලැබුණු ආහාරය කුමක්ද?", "යව හාල්", "කිරිපිඬු", "සුවඳැල් බත්", "මී පිඬු", "දුර්භික්ෂ සමයේ අශ්ව වෙළඳුන්ගෙන් ලැබුණු යව හාල් කොටා වැළඳූහ."),
    q("රූප ශෝභාවට වඩා ශීල ගුණය අගය කර සිය ඇසක් පවා ගලවා දීමට සූදානම් වූ තෙරණිය කවුද?", "සුභා ජීවකම්බවනිකා තෙරණිය", "ඛේමා තෙරණිය", "ඉසිදාසී තෙරණිය", "පටාචාරා තෙරණිය", "රූපයේ ඇති නිසරු බව පෙන්වා සුභා තෙරණිය සිය ඇස ගලවා දුන් බව ථේරී ගාථාවල එයි."),
    q("භික්ෂුණීන් අතරින් 'ධුතාංගධාරීන් අතර අග්‍ර' තනතුර ලැබූ තෙරණිය කවුද?", "කිසාගෝතමී තෙරණිය", "පටාචාරා තෙරණිය", "සිගාලමාතා තෙරණිය", "සෝණා තෙරණිය", "රළු සිවුරු දරමින් ධුතාංග රැකි කිසාගෝතමී තෙරණිය අග්‍ර වූවාය."),
    q("ගිලානෝපස්ථාන උපාසිකාවන් අතර අග්‍රස්ථානය ලැබූ කාන්තාව කවුද?", "සුප්පියා උපාසිකාව", "විශාඛා උපාසිකාව", "කාණාමාතාව", "මල්ලිකා දේවිය", "රෝගී භික්ෂුවකට ගිලන් පස හා ආහාර සැපයීමට කැපවූ සුප්පියා උපාසිකාව අග්‍ර විය."),
    q("මෛත්‍රී විහරණයෙන් අග්‍ර උපාසිකාව ලෙස බුදුරදුන්ගෙන් පැසසුම් ලැබුවේ කවුද?", "සාමාවතී උපාසිකාව", "විශාඛා උපාසිකාව", "කාලී උපාසිකාව", "නකුලමාතාව", "සතුරු මාගන්දියා කෙරෙහි පවා මෛත්‍රිය වැඩූ සාමාවතී අග්‍ර වූවාය."),
    q("බුදුරදුන් කෙරෙහි ඉතා විශ්වාසවන්තයන් අතර අග්‍ර වූ උපාසිකාව කවුද?", "නකුලමාතා උපාසිකාව", "කාලී උපාසිකාව", "සාමාවතී උපාසිකාව", "උත්තරා උපාසිකාව", "නකුලපිතා හා නකුලමාතා විස්සාසිකයන් අතර අග්‍ර විය."),
    q("බුදුන් නොදැක ඇසූ පමණින් ශ්‍රද්ධාව උපදවා අනුශ්‍රැති ප්‍රසාදයෙන් අග්‍ර වූ උපාසිකාව කවුද?", "කුරරඝරිකා කාලී උපාසිකාව", "විශාඛා උපාසිකාව", "ඛුජ්ජුත්තරා උපාසිකාව", "සුජාතා උපාසිකාව", "ධර්මය ශ්‍රවණය කළ පමණින් කාලී උපාසිකාව සෝවාන් විය."),
    q("භික්ෂූන්ට නියම කළ වස් කාලය කුමන පොහෝ දිනකින් ආරම්භ වී කවදා අවසන් වේද?", "ඇසළ පෝයෙන් පසු වප් පෝය දක්වා", "වෙසක් පෝයෙන් පසු ඇසළ පෝය දක්වා", "නවම් පෝයෙන් පසු බක් පෝය දක්වා", "ඉල් පෝයෙන් පසු දුරුතු පෝය දක්වා", "මාස තුනක වස් කාලය ඇසළ අව පෑළවියෙන් ඇරඹී වප් පෝයෙන් පවාරණය වේ."),
    q("සැරියුත් මහරහතන් වහන්සේගේ උපන් ගම කුමක්ද?", "නාලක ගම", "උරුවෙල ගම", "සේනානි ගම", "බේළුව ගම", "මගධයේ නාලක බමුණු ගමේදී උපතිස්ස කුමරු උපන්නේය."),
    q("බුදුරජාණන් වහන්සේගේ ගිහි කල පුත්‍ර රාහුල කුමරුගේ මෑණියන් කවුද?", "යසෝධරා දේවිය", "මහාමායා දේවිය", "ප්‍රජාපතී ගෝතමිය", "සුන්දරී නන්දා දේවිය", "භද්දකච්චානා හෙවත් යසෝධරා දේවිය රාහුල කුමරුගේ මෑණියන්ය."),
    q("අනාථව සිටි රෝගී පූතිගත්ත තිස්ස භික්ෂුවට බුදුරදුන් සමඟ ගොස් උපස්ථාන කළේ කවුද?", "ආනන්ද හිමි", "සැරියුත් හිමි", "මුගලන් හිමි", "උපාලි හිමි", "පූතිගත්ත තිස්ස හිමියන් නහවා පිරිසිදු කිරීමට ආනන්ද හිමියෝ සහාය වූහ."),
    q("මහලු වියේ පැවිදි වී සැරියුත් හිමියන්ගේ උපකාරයෙන් රහත් වූ බමුණා කවුද?", "රාධ බමුණා", "සෝණදණ්ඩ බමුණා", "පිංගිය බමුණා", "බ්‍රහ්මායු බමුණා", "සැරියුත් හිමියන් රාධ බමුණා පැවිදි කර නිවන් මඟට උදව් කළහ."),
    q("බුදුරදුන් ජීවමාන සමයේදී සුනාපරන්ත දේශයට ධර්මදූත සේවයේ වැඩම කළ ධෛර්යවත් හිමියන් කවුද?", "පුණ්ණ හිමි", "මහා කච්චායන හිමි", "මහින්ද හිමි", "සෝණ හිමි", "සුනාපරන්තයේ දරුණු මිනිසුන් අතර ඉවසීමෙන් දහම් දෙසූ පුණ්ණ හිමි රහත් වූහ."),
    q("දුප්පතුන්ට පින් රැස් කර ගැනීමට ඉඩ දෙමින් දුගී මගීන්ගේ දානය කැමති වූ මහතෙරුන් කවුද?", "මහා කාශ්‍යප හිමි", "ආනන්ද හිමි", "උපාලි හිමි", "මුගලන් හිමි", "මහා කාශ්‍යප හිමියන් නිරෝධ සමාපත්තියෙන් නැගිට දුගීන් වෙත වැඩම කළහ."),
    q("කිඹුල්වත් නුවර මැදුරේ කවුළුවෙන් බලා සිට නරසීහ ගාථා පැවසුවේ කවුද?", "යසෝධරා දේවිය", "මහා ප්‍රජාපතී ගෝතමිය", "සුදොවුන් රජු", "කිසාගෝතමිය", "'සක්කා තේ නරවරසීහ...' යන ගාථාවලින් රාහුල කුමරුට බුදුන් පෙන්වූවාය."),
    q("භික්ෂුණීන් අතරින් පෙර ජාති දැකීමේ ඥානයෙන් අග්‍ර වූ තෙරණිය කවුද?", "භද්දා කාපිලානි තෙරණිය", "සෝණා තෙරණිය", "සකුලා තෙරණිය", "නන්දා තෙරණිය", "පෙර ජාති සිහි කිරීමේ ඥානයෙන් භද්දා කාපිලානි තෙරණිය අග්‍ර වූවාය."),
    q("සුදොවුන් රජුගේ ඉල්ලීම පරිදි බුදුරදුන් පැනවූ විනය නීතිය කුමක්ද?", "මව්පිය අවසරය නැතිව දරුවන් පැවිදි නොකිරීම", "රජවරුන් පැවිදි නොකිරීම", "සිවුරු නොදීම", "පිඬුසිඟා නොයෑම", "නන්ද හා රාහුල පැවිදි වීමෙන් ඇති වූ ශෝකය නිසා රජු මෙම ඉල්ලීම කළේය."),
    q("බුදුරදුන් වදාළ 'දඹදිව සතර සංවේගජනක ස්ථාන' අතරට අයත් නොවන නගරය කුමක්ද?", "සැවැත් නුවර", "ලුම්බිණිය", "බුද්ධගයාව", "ඉසිපතනය", "ලුම්බිණිය, බුද්ධගයාව, ඉසිපතනය හා කුසිනාරාව සිව්වැදෑරුම් සංවේගජනක ස්ථාන වේ."),
    q("බුදුරදුන් වෙනුවෙන් ජේතවනාරාමයේ ආනන්ද හිමියන් රෝපණය කරවූ බෝධි ශාඛාව කුමක්ද?", "ආනන්ද බෝධිය", "මහා බෝධිය", "සුජාතා බෝධිය", "නිග්‍රෝධ බෝධිය", "බුදුරදුන් නොමැති විට වන්දනා කිරීමට ජේතවනයේ ආනන්ද බෝධිය රෝපණය කෙරිණි."),
    q("පංච මහා විලෝකනයේදී බෝසතාණන් වහන්සේ පරීක්ෂා කරන කරුණු පහට අයත් නොවන්නේ කුමක්ද?", "සේනා ශක්තිය", "කාලය", "දීපය", "කුලය", "කාලය, දීපය, දේශය, කුලය හා මව යන පහ පංච මහා විලෝකනයයි."),
    q("බුදුරජාණන් වහන්සේගේ ශරීරයේ පිහිටි මහා පුරුෂ ලක්ෂණ ගණන කීයක්ද?", "දෙතිසකි", "අසූවකි", "සූවිස්සකි", "සොළොසකි", "දෙතිස් මහා පුරුෂ ලක්ෂණ බුදු සිරුරේ පිහිටා තිබුණි."),
    q("ධවල සේසත් යටදීම ධර්මය අසා අරහත් ඵලයට පත්ව පිරිනිවන් පෑ රජු කවුද?", "සුද්ධෝදන රජතුමා", "මහානාම රජු", "බිම්බිසාර රජු", "සුප්පබුද්ධ රජු", "සුද්ධෝදන රජු ගිහි වතින්ම රහත් වී පිරිනිවන් පෑහ."),
    q("රාහුල කුමරු උපන් විට කුමරු පැවසූ වදන නිසා එතුමාට තැබූ නම කුමක්ද?", "රාහුල", "නන්ද", "තිස්ස", "සිද්ධාර්ථ", "'රාහු ජාතෝ බන්ධනං ජාතං' යයි වදාළ නිසා රාහුල යන නම තැබිණි."),
    q("දීපංකර බුදුරදුන් හමුවේ සුමේධ තාපසතුමා නියත විවරණ ලැබූ කාලය කෙතෙක්ද?", "සාරාසංඛ්‍ය කල්ප ලක්ෂයකට පෙර", "සියවස් දහයකට පෙර", "වසර දහසකට පෙර", "කල්ප දෙකකට පෙර", "රම්ම නුවරදී දීපංකර බුදුරදුන්ගෙන් ගෞතම බුදු වන බවට නියත විවරණ ලැබීය."),
    q("නියත විවරණ ලැබීමට සම්පූර්ණ විය යුතු ධර්මතා අට හඳුන්වන්නේ කුමන නමකින්ද?", "අෂ්ට ධර්ම සමෝධානය", "අෂ්ට ලෝක ධර්මය", "අෂ්ට සමාපත්තිය", "අෂ්ට ගරු ධර්මය", "මනුෂ්‍යත්වය, ලිංග සම්පත්තිය ආදී කරුණු අට අෂ්ට ධර්ම සමෝධානයයි."),
    q("කාන්තා නුවණ පිළිබඳ මාරයාගේ අභියෝගයට අභීතව පිළිතුරු දුන් තෙරණිය කවුද?", "සෝමා තෙරණිය", "උත්තමා තෙරණිය", "චාලා තෙරණිය", "උපචාලා තෙරණිය", "සිත සමාහිත නම් ස්ත්‍රී බව බාධාවක් නොවන බව සෝමා තෙරණිය පැවසුවාය."),
    q("වතුර බහින කාණු හා ඊතණ අදින වඩුවන් දැක සිත දමනය කර රහත් වූ කුඩා හිමියන් කවුද?", "පණ්ඩිත සාමණේරයන්", "රාහුල සාමණේරයන්", "සුමන සාමණේරයන්", "තිස්ස සාමණේරයන්", "සැරියුත් හිමියන්ගේ ශිෂ්‍ය පණ්ඩිත සාමණේරයන් සත් හැවිරිදි වියේදී රහත් විය."),
    q("අනේපිඬු සිටුතුමාගේ ගිහි නාමය කුමක්ද?", "සුදත්ත", "මිගාර", "ඝෝෂිත", "කුක්කුට", "අනාථයන්ට පිඬු සිඟා දීම නිසා සුදත්ත සිටුතුමා අනේපිඬු නම් විය."),
    q("විශාඛා සිටු දියණියගේ පියාණන් වූ සිටුතුමා කවුද?", "ධනංජය සිටුතුමා", "මිගාර සිටුතුමා", "සුදත්ත සිටුතුමා", "පූර්ණක සිටුතුමා", "සාකේත නුවර ධනංජය සිටුතුමාගේ දියණිය විශාඛාව සත් හැවිරිදි වියේදීම සෝවාන් විය."),
    q("විශාඛා උපාසිකාව සිය මාමණ්ඩිය බුදුදහමට යොමු කළ නිසා ලද ගෞරව නාමය කුමක්ද?", "මිගාරමාතා", "ධම්මදින්නා", "රාජමාතා", "සංඝමාතා", "විශාඛාව මිගාර සිටුට දහම් මඟ පෙන්වූ බැවින් මිගාරමාතා යැයි ඇමතීය."),
    q("බුදුරදුන්ට අසත්‍ය චෝදනා නැගීමට උත්සාහ කර පිරිස ඉදිරියේ ලැජ්ජාවට පත් වූයේ කවුද?", "චිංචිමානවිකාව", "සුන්දරී පරිබ්‍රාජිකාව", "මාගන්දියා", "කුණ්ඩලකේසී", "ලී මිටියක් බැඳ ගෙන ගර්භණී ලෙස රඟපෑ චිංචිමානවිකාවගේ බොරුව හෙළි විය."),
    q("අජපල් නුගරුක මුලදී මාරයා විසින් බුදුරදුන් ඉදිරියට එවූ දූවරුන් තිදෙනා කවුද?", "තණ්හා, රති, රගා", "මෝහ, දෝස, ලෝභ", "ජාති, ජරා, මරණ", "ශ්‍රද්ධා, සති, ප්‍රඥා", "මාර දූවරුන්ගේ කිසිදු උපායක් බුදුරදුන් කෙරෙහි බල නොපෑවේය."),
    q("හෙළ අටුවා පාලි භාෂාවට පරිවර්තනය කළ මහා අටුවාචාරීන් වහන්සේ කවුද?", "බුද්ධඝෝෂ හිමි", "මහින්ද හිමි", "මහා කාශ්‍යප හිමි", "නාගසේන හිමි", "මහාවිහාර සම්ප්‍රදායේ හෙළ අටුවා පාලියට නැගුවේ බුද්ධඝෝෂ හිමියන්ය."),
    q("ධර්ම භාණ්ඩාගාරික ආනන්ද හිමි පිරිනිවන් පෑවේ කුමන ස්ථානයකදීද?", "රෝහිණී නදිය මැද අහසේදී", "නේරංජනා නදිය මැද", "ගංගා නදිය මැද", "අචිරවතී නදිය මැද", "දෙපිරිසකගේ ධාතු ගැටුම් වැළැක්වීමට රෝහිණී නදිය මැද පිරිනිවන් පෑහ."),
    q("ආනන්ද හිමියන් අරහත්වයට පත් වූයේ කුමන ඉරියව්වකදීද?", "සැතපෙන ඉරියව්වට යන අතරතුර", "සක්මන් කරමින් සිටියදී", "වාඩි වී සිටියදී", "සිටගෙන සිටියදී", "ප්‍රථම සංගායනාවට පෙර රාත්‍රියේ සිව් ඉරියව්වෙන් තොරව රහත් වූ එකම තෙරුන්ය."),
    q("මිලින්ද රජුගේ සියලු දාර්ශනික ප්‍රශ්න විසඳූ ශ්‍රේෂ්ඨ බෞද්ධ හිමිනම කවුද?", "නාගසේන හිමි", "මොග්ගලීපුත්ත තිස්ස හිමි", "අශ්වඝෝෂ හිමි", "නාගාර්ජුන හිමි", "මිලින්ද ප්‍රශ්නය නම් ග්‍රන්ථය නාගසේන හිමි හා මිලින්ද රජුගේ සංවාදයයි."),
    q("බුදුරදුන් සත් සතියෙන් හත්වන සතිය ගත කළ වෘක්ෂ මූලය කුමක්ද?", "රාජායතන රුක මුල", "අජපල් නුගරුක මුල", "මුචලින්ද විල අසල", "බෝධි මූලයේ", "තපස්සු භල්ලුක වෙළඳුන් හමුවූයේ රාජායතන කිරිපලු රුක මුලදීය."),
    q("නන්ද හිමියන්ට කාමයෙහි ආදීනව වටහා දීමට බුදුරදුන් පෙන්වූ උපමාව කුමක්ද?", "වඳුරෙකු හා දිව්‍ය අප්සරාවන්ගේ උපමාව", "වීණා තත් උපමාව", "දිය බුබුළු උපමාව", "රථ උපමාව", "හිමාලයේ දසුන හා දෙව්ලොව දැක්වීමෙන් නන්ද හිමි රහත් වූහ."),
    q("බුදු සසුනේ සිංහනාද කරන භික්ෂූන් අතර අග්‍රස්ථානය ලැබූ හිමියන් කවුද?", "පිණ්ඩෝල භාරද්වාජ හිමි", "මහා කාශ්‍යප හිමි", "වංගීස හිමි", "ආනන්ද හිමි", "සැක ඇති අයට ප්‍රශ්න අසන ලෙස අභීතව පැවසූ නිසා අග්‍ර විය."),
    q("මිහිඳු හිමියන් සමඟ ලක්දිවට වැඩම කළ ධර්මදූත පිරිසේ සිටි ගිහි උපාසකයා කවුද?", "භණ්ඩුක උපාසක", "සුමන සාමණේර", "ඉට්ඨිය හිමි", "උත්තිය හිමි", "සංඝමිත්තා තෙරණියගේ ඥාති පුත් භණ්ඩුක මිහින්තලේදී පැවිදිව රහත් විය."),
    q("මිහිඳු හිමිගෙන් පසු ලංකාවේ ප්‍රථම සිංහල භික්ෂුව ලෙස පැවිදි වූයේ කවුද?", "මහා අරිට්ඨ කුමරු", "මහානාග කුමරු", "උත්තිය කුමරු", "තිස්ස කුමරු", "දේවානම්පියතිස්ස රජුගේ බෑණනුවන් වූ අරිට්ඨ කුමරු ප්‍රථම සිංහල මහරහතන් වහන්සේ විය."),
    q("ලංකාවේ ප්‍රථම භික්ෂුණිය ලෙස පැවිදි වූ රාජකීය කාන්තාව කවුද?", "අනුලා දේවිය", "විහාරමහා දේවිය", "සෝමා දේවිය", "ලීලාවතී රැජින", "අනුලා දේවිය පන්සියයක් කතුන් සමඟ සංඝමිත්තා තෙරණියගෙන් පැවිද්ද ලැබුවාය."),
    q("ධනපාල හෙවත් මච්ඡරිය කෝසිය සිටුතුමාගේ මසුරුකම දුරු කළේ කවුද?", "මුගලන් හිමි", "සැරියුත් හිමි", "ආනන්ද හිමි", "මහා කාශ්‍යප හිමි", "මුගලන් හිමියන් ඍද්ධි බලයෙන් සිටුතුමා දමනය කර දන් දීමට යොමු කළහ."),
    q("මරණ මංචකයේදී බුදුරදුන් කෙරෙහි සිත පහදා ගැනීමෙන් දෙව්ලොව උපන් තරුණයා කවුද?", "මට්ටකුණ්ඩලී", "සෝපාක", "සුනීත", "නන්ද", "මසුරු පියෙකුගේ පුතෙකු වූ මට්ටකුණ්ඩලී තව්තිසා දෙව්ලොව උපත ලැබීය."),
    q("සැරියුත් මහරහතන් වහන්සේගේ පියාණන් වූ බමුණාගේ නම කුමක්ද?", "වංගන්ත බමුණා", "සුදත්ත බමුණා", "සෝණදණ්ඩ බමුණා", "බ්‍රහ්මායු බමුණා", "සාරී බැමිණියගේ සැමියා වංගන්ත බමුණා සැරියුත් හිමිගේ පියාය."),
    q("පළමු ධර්ම දූත පිරිස ලෙස බුදුරදුන් දෙසූ 'චරථ භික්ඛවේ චාරිකං' පිරිසේ සිටි රහතුන් ගණන කීයද?", "සැට නමකි", "අසූ නමකි", "සිය නමකි", "පන්සිය නමකි", "යස කුලපුත්‍ර ඇතුළු යහළුවන් සමඟ රහතන් වහන්සේලා 60 නමක් විය."),
    q("එක් මඟකින් දෙදෙනෙකු නොයන ලෙස බුදුරදුන් ධර්ම දූත පිරිසට නියම කළේ ඇයි?", "වැඩි පිරිසකට ධර්මය ලබාදීමට", "ආහාර හිඟකම නිසා", "ගමන් වියදම් අඩු කිරීමට", "කාලගුණික හේතු නිසා", "සෑම දිශාවකම ජනතාවට සත්‍ය ධර්මය බෙදා දීම එහි අරමුණ විය."),
    q("බේළුව ගමේදී රෝගී වූ අවස්ථාවේදී බුදුරදුන් ආනන්ද හිමිට වදාළ ප්‍රධාන උපදේශය කුමක්ද?", "තමාම තමාට පිහිට කරගන්නා ලෙස", "දේවදත්ත හිමි සමඟ එක්වන ලෙස", "රජුගෙන් ආරක්ෂාව පතන ලෙස", "වනයට පලා යන ලෙස", "'අත්තදීපා විහරථ ධම්මදීපා' ලෙස ධර්මය සරණ කරගන්නා ලෙස වදාළහ."),
    q("පිළිකුල් භාවනාවෙන් කලකිරුණු භික්ෂූන්ට බුදුරදුන් ලබා දුන් නව කමටහන කුමක්ද?", "ආනාපානසති භාවනාව", "මෛත්‍රී භාවනාව", "බුද්ධානුස්සති භාවනාව", "කසිණ භාවනාව", "වග්ගුමුදා ගං තෙර භික්ෂූන්ට සිසිල් සුවදායක ආනාපානසතිය දේශනා කළහ."),
    q("නිවන් මඟ සප්ත විසුද්ධිය රථ හතකට උපමා කර දැක්වෙන සූත්‍රය කුමක්ද?", "රථවිනීත සූත්‍රය", "මහාමංගල සූත්‍රය", "සච්චවිභංග සූත්‍රය", "අනත්තලක්ඛණ සූත්‍රය", "සැරියුත් හිමි හා පුණ්ණ මන්තානිපුත්ත හිමි අතර සංවාදයක් ලෙස මෙය දේශනා විය."),
    q("බුදුරදුන්ගේ ආදාහනයෙන් පසු අඟුරු ගෙන ගොස් චෛත්‍යයක් ඉදිකළ රජවරු කවුද?", "පිප්ඵලීවනයේ මෞර්ය රජවරු", "විශාලාවේ ලිච්ඡවී රජවරු", "පාවා නුවර මල්ල රජවරු", "කපිලවස්තුවේ ශාක්‍ය රජවරු", "මෞර්ය රජවරු අංගාර චෛත්‍යය ඉදිකළ අතර ද්‍රෝණ බමුණා කුම්භ චෛත්‍යය කළේය."),
    q("පැරණි බිරිඳ හා දරුවා දැක ඇලීමෙන් තොරව නිහඬව ඉවසූ බුදු පැසසුම් ලත් හිමියන් කවුද?", "සංගාමජී හිමි", "රේවත හිමි", "අංගුලිමාල හිමි", "නන්ද හිමි", "ඇලීම් ගැටීම්වලින් තොරව සංගාමජී හිමි ආර්ය ගුණය ප්‍රකට කළහ."),
    q("සිදුහත් කුමරු හා යසෝධරා දේවිය විවාහ වන විට දෙදෙනාගේ වයස කීයද?", "අවුරුදු 16 කි", "අවුරුදු 18 කි", "අවුරුදු 20 කි", "අවුරුදු 25 කි", "ශිල්ප දැක්වීමෙන් පසු සොළොස් හැවිරිදි වියේදී විවාහ මංගල්‍යය සිදුවිය."),
    q("සිදුහත් කුමරු මහාභිනිෂ්ක්‍රමණය කරන විට උන්වහන්සේගේ වයස කීයද?", "අවුරුදු 29 කි", "අවුරුදු 25 කි", "අවුරුදු 35 කි", "අවුරුදු 30 කි", "වයස අවුරුදු 29 දී නික්මී වසර 6 ක් දුෂ්කරක්‍රියා කොට 35 දී බුදු වූහ."),
    q("බුදුරජාණන් වහන්සේ පිරිනිවන් පා වදාළ වයස කීයද?", "අවුරුදු 80 කි", "අවුරුදු 75 කි", "අවුරුදු 85 කි", "අවුරුදු 90 කි", "වසර 45 ක් පුරා ධර්ම චාරිකාවේ යෙදී අසූ වියේදී පිරිනිවන් පෑහ."),
    q("උරුවෙල, නදී හා ගයා කාශ්‍යප යන තුන්බෑ ජටිලයන්ගේ මුළු පිරිස කොපමණද?", "දහසකි", "පන්සියයකි", "තුන්සියයකි", "දෙසියයකි", "උරුවෙල කාශ්‍යප 500, නදී කාශ්‍යප 300, ගයා කාශ්‍යප 200 ලෙස මුළු පිරිස 1000 කි."),
    q("ධම්මසේනාපති සැරියුත් හිමියන්ගේ රහත් වූ ගිහි සොහොයුරියන් තිදෙනා කවුරුන්ද?", "චාලා, උපචාලා, සීසූපචාලා", "ඛේමා, පටාචාරා, සෝමා", "නන්දා, සුභා, රෝහිණී", "චන්දා, ධම්මා, සුමනා", "ඔවුන් තිදෙනාම පැවිදි වී අරහත් ඵලයට පත් වූහ."),
    q("තම ශිෂ්‍ය අම්බට්ඨ පරාජය වීමෙන් පසු බුදුරදුන් වෙත පැමිණ පැහැදුණු බ්‍රාහ්මණ පඬිවරයා කවුද?", "පොක්ඛරසාති බමුණා", "සෝණදණ්ඩ බමුණා", "කූටදන්ත බමුණා", "තේවිජ්ජ බමුණා", "අම්බට්ඨ සූත්‍රය අවසානයේ පොක්ඛරසාති බමුණා තෙරුවන් සරණ ගියේය."),
    q("කුසිනාරාවට වැඩි ගමනේදී පිපාසය සංසිඳුවා ගැනීමට කකුත්ථා නදියෙන් පැන් ගෙන ආවේ කවුද?", "ආනන්ද හිමි", "අනුරුද්ධ හිමි", "මහා කාශ්‍යප හිමි", "උපවාන හිමි", "කැළඹී තිබූ නදී ජලය බුදුරදුන්ගේ ආනුභාවයෙන් පැහැදිලි විය."),
    q("සිද්ධාර්ථ කුමාරයා ඉපදී පස්වන දිනයේ බමුණන් කැඳවා පැවැත්වූ මංගල්‍යය කුමක්ද?", "නම් තැබීමේ මංගල්‍යය", "වප් මඟුල් උළෙල", "අභිෂේක මංගල්‍යය", "ශිල්ප දැක්වීම", "බමුණන් 108 ක් කැඳවා නම් තැබීමේ මංගල්‍යය පැවැත්වීය."),
    q("භද්දකච්චානා හෙවත් යසෝධරා තෙරණිය ලැබූ අග්‍රස්ථානය කුමක්ද?", "මහා අභිඥාලාභී භික්ෂුණීන් අතර අග්‍ර", "ධර්ම කථික භික්ෂුණීන් අතර අග්‍ර", "විනයධර භික්ෂුණීන් අතර අග්‍ර", "ඍද්ධිමත් භික්ෂුණීන් අතර අග්‍ර", "යසෝධරා තෙරණිය මහා අභිඥාවෙන් අග්‍ර වූවාය."),
    q("අනුරුද්ධ හිමියන්ගේ ශිෂ්‍යයෙකු ලෙස සත් හැවිරිදි වියේදීම රහත් වූ සාමණේරයන් කවුද?", "සුමන සාමණේරයන්", "රාහුල සාමණේරයන්", "සෝපාක සාමණේරයන්", "පණ්ඩිත සාමණේරයන්", "අනුරුද්ධ හිමියන්ගේ අතවැසි සුමන සාමණේර ඍද්ධි බලයෙන් අනෝතත්ත විලෙන් පැන් ගෙනාවේය."),
    q("තම මියගිය පියාගේ සොහොන නොව, සැමියා හා දෙමාපියන් වෙනුවෙන් දැඩි සෙනෙහසින් කටයුතු කළ නකුලපිතා කාගේ සැමියාද?", "නකුලමාතාවගේ", "විශාඛාවගේ", "සාමාවතියගේ", "මල්ලිකාවගේ", "ගිහි විස්සාසිකයන් අතර නකුලපිතා හා නකුලමාතා අග්‍ර වූහ."),
    q("සත් හැවිරිදි නිග්‍රෝධ සාමණේරයන්ගෙන් බණ අසා බුදුදහම වැළඳගත් අධිරාජයා කවුද?", "ධර්මාශෝක අධිරාජයා", "බිම්බිසාර රජු", "කාලාශෝක රජු", "දේවානම්පියතිස්ස රජු", "අප්පමාද වග්ගයේ දේශනාවෙන් අශෝක රජු පැහැදුණි."),
    q("රාමග්‍රාමයේ කෝලිය රජවරු නිදන් කළ බුදුරදුන්ගේ ධාතූන් පසුව ලංකාවේ තැන්පත් කළේ කොහිද?", "රුවන්වැලි මහා සෑයේ", "ථූපාරාමයේ", "මිරිසවැටියේ", "ජේතවනාරාමයේ", "සෝණුත්තර හිමියන් නාග ලොවින් වැඩමවා රුවන්වැලි සෑයේ තැන්පත් කළහ."),
    q("දෙවියෙකුද මනුෂ්‍යයෙකුදැයි විමසූ බමුණාට 'මම බුද්ධ වෙමි' යි වදාළේ කාටද?", "ද්‍රෝණ බමුණාට", "උපක ආජීවකයාට", "සච්චකට", "වස්සකාරට", "ලෝකයේ සියලු කෙලෙස් නැසූ බුද්ධ බව ද්‍රෝණ බමුණාට පැහැදිලි කළහ."),
    q("කළගුණ සැලකීමට තමා නොමැතිව සිටි රෝගී සැරියුත් හිමියන්ගේ ගුරු උපස්ථානය අගය කළේ කවුද?", "බුදුරජාණන් වහන්සේ", "මහා කාශ්‍යප හිමි", "මුගලන් හිමි", "ආනන්ද හිමි", "අස්සජී හිමියන් වැඩ සිටින දිශාවට හිසලා සැරියුත් හිමි නමස්කාර කළහ."),
    q("පෙර නොඇසූ විරූ ධර්මය තමා විසින්ම අවබෝධ කර අන් අයට ද දේශනා කරන්නා කවුද?", "සම්මා සම්බුදුරජාණන් වහන්සේ", "පසේ බුදුරජාණන් වහන්සේ", "සාරිපුත්ත මහරහතන් වහන්සේ", "අනාගාමී උතුමන්", "සම්මා සම්බුදුන් වහන්සේ තමන් ද නිවන් දැක අන් අයට ද නිවන් මඟ දෙසති.")
  )
}
